let mut current_group: String = String::new();
let mut open_braces: i32 = 0;
for c in paren_string.chars() {
    if c == '(' {
        open_braces += 1;
    } else if c == ')' {
        open_braces -= 1;
    } else if c == ' ' {
        continue;
    } else {
        panic!("Invalid character in input string");
    }
    current_group.push(c);
    if open_braces == 0 {
        groups.push(current_group.clone());
        current_group.clear();
    }
}
