let mut beats = Vec::new();
let mut i = 0;
let chars: Vec<char> = music_string.chars().collect();
while i < chars.len() {
    match chars[i] {
        'o' => {
            if i + 1 < chars.len() && chars[i + 1] == '|' {
                beats.push(2);
                i += 2;
            } else {
                beats.push(4);
                i += 1;
            }
        }
        '.' => {
            if i + 1 < chars.len() && chars[i + 1] == '|' {
                beats.push(1);
                i += 2;
            } else {
                // Unexpected format; skip
                i += 1;
            }
        }
        _ => {
            // Skip spaces or other characters
            i += 1;
        }
    }
}
